with latest as (select *, row_number() over (partition by device_code order by reading_ts desc, id asc) as rn from device_readings qualify rn = 1) select device_code, date_trunc('day', reading_ts) as activity_day, bit_or(status_bits) as status_bits_bit_or, percentile_approx(status_bits, 0.95) as status_bits_p95, count_if(device_code = 'DV-02') as dv_02_events, percentile_approx(humidity, 0.5) as humidity_p50, avg(humidity) filter (where device_code = 'DV-01') as dv_01_avg_humidity from latest group by device_code, date_trunc('day', reading_ts) order by dv_02_events desc
